const slugToCat = Object.fromEntries(categories.map(c=>[c.slug,c.label]));
const PRICE_LOCALE={fr:'fr-FR',en:'en-IE',es:'es-ES',de:'de-DE'};
const fmtIn = (n,loc) => new Intl.NumberFormat(loc,{style:'currency',currency:'EUR',maximumFractionDigits:2}).format(Number(n)||0);
const fmt = n => fmtIn(n, PRICE_LOCALE[getLang()]||'fr-FR');
const fmtFR = n => fmtIn(n,'fr-FR');
const readLocal=(k,fb)=>{try {const v=JSON.parse(localStorage.getItem(k)||'null');return v??fb;}catch{return fb;}};
const saveLocal=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));}catch{}};
const hashPath = ()=>decodeURIComponent((location.hash||'#/').slice(1));
const go = p => { location.hash='#'+p; window.scrollTo({top:0,behavior:'instant'}); };
const slugify=s=>(s||'article').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');

