function Icon({name,size=20,fill='none'}) {return <svg width={size} height={size} viewBox="0 0 24 24" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" fill={fill} aria-hidden="true">{paths[name]||paths.arrow}</svg>}
