const PAYMENT_METHODS={sumup:{label:'Carte bancaire (SumUp)',small:'Visa, Mastercard… via un lien de paiement sécurisé SumUp'},paypal:{label:'PayPal',small:'Compte PayPal ou carte via un lien de paiement sécurisé PayPal'}};
function buildOrderText(order){
 const c=order.customer||{};const ship=SHIPPING_OPTIONS[order.deliveryMethod]||{};
 const lines=(order.lines||[]).map(l=>`- ${l.title} × ${l.quantity} : ${fmtFR(l.unitPrice*l.quantity)} (${fmtFR(l.unitPrice)} / unité)`).join('\n');
 return [
  `Bonjour Keigh’s Corner,`,``,
  `Je souhaite passer la commande suivante.`,``,
  `Référence : ${order.id}`,`Date : ${order.date}`,``,
  `ARTICLES`,lines,``,
  `Sous-total : ${fmtFR(order.subtotal)}`,
  `Livraison (estimation) : ${ship.label||''} ${ship.carrier?'· '+ship.carrier:''} · ${fmtFR(order.shippingCost)}`,
  `Total estimé : ${fmtFR(order.amount)}`,``,
  `PAIEMENT SOUHAITÉ : ${PAYMENT_METHODS[order.paymentChoice]?.label||''}`,``,
  `COORDONNÉES`,
  `${c.firstName} ${c.lastName}`,`E-mail : ${c.email}`,`Téléphone : ${c.phone}`,
  `Adresse : ${c.street}${c.line2?', '+c.line2:''}, ${c.postcode} ${c.city}, ${c.country}`,
  order.deliveryMethod==='pickup'?`Point relais souhaité : ${c.pickupName}`:null,
  c.message?`\nMessage : ${c.message}`:null,``,
  `Merci de me confirmer la disponibilité et de m’envoyer le lien de paiement.`
 ].filter(x=>x!==null).join('\n');
}
