   const i=new Image(),url=URL.createObjectURL(file);i.onload=()=>{const scale=Math.min(1,980/i.width,1100/i.height);const c=document.createElement('canvas');c.width=Math.max(1,Math.round(i.width*scale));c.height=Math.max(1,Math.round(i.height*scale));c.getContext('2d').drawImage(i,0,0,c.width,c.height);URL.revokeObjectURL(url);resolve(c.toDataURL('image/jpeg',.68));};i.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Image illisible'))};i.src=url;
